#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <climits>
using namespace std;

using pii = pair<int, int>;

const int INF = 1000000000;

struct Edge {
    int to, capacity, rev_idx;
};

class MaxFlowSolver {
public:
    int nodes;
    vector<vector<Edge>> graph;
    vector<int> level, iter;

    MaxFlowSolver(int n) : nodes(n), graph(n), level(n), iter(n) {}

    void addEdge(int u, int v, int cap) {
        graph[u].push_back({v, cap, (int)graph[v].size()});
        graph[v].push_back({u, 0, (int)graph[u].size() - 1});
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : graph[u]) {
                if (level[e.to] == -1 && e.capacity > 0) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        for (int& i = iter[u]; i < (int)graph[u].size(); ++i) {
            Edge& e = graph[u][i];
            if (level[e.to] == level[u] + 1 && e.capacity > 0) {
                int pushed = dfs(e.to, t, min(flow, e.capacity));
                if (pushed > 0) {
                    e.capacity -= pushed;
                    graph[e.to][e.rev_idx].capacity += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int computeMaxFlow(int s, int t) {
        int total = 0;
        while (bfs(s, t)) {
            fill(iter.begin(), iter.end(), 0);
            int pushed;
            while ((pushed = dfs(s, t, INF)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    vector<string> field(n), capsule(n);
    int src = 2 * n * n, dst = src + 1;
    MaxFlowSolver mf(2 * n * n + 2);

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i) {
        cin >> field[i];
        for (int j = 0; j < n; ++j) {
            if (field[i][j] == 'Z') {
                zx = i; zy = j;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> capsule[i];
        for (int j = 0; j < n; ++j) {
            if (isdigit(capsule[i][j])) {
                mf.addEdge(i * n + j + n * n, dst, capsule[i][j] - '0');
            }
        }
    }

    vector<vector<int>> distZ(n, vector<int>(n, INF));
    queue<pii> q;
    distZ[zx][zy] = 0;
    q.push({zx, zy});
    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (distZ[x][y] == t) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distZ[nx][ny] == INF) {
                distZ[nx][ny] = distZ[x][y] + 1;
                if (isdigit(capsule[nx][ny])) {
                    mf.addEdge(zx * n + zy, nx * n + ny + n * n, INF);
                }
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(field[i][j])) {
                mf.addEdge(src, i * n + j, field[i][j] - '0');
                vector<vector<int>> distS(n, vector<int>(n, INF));
                queue<pii> q2;
                distS[i][j] = 0;
                q2.push({i, j});
                while (!q2.empty()) {
                    auto [x, y] = q2.front(); q2.pop();
                    if (distS[x][y] == t) continue;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distS[nx][ny] == INF) {
                            distS[nx][ny] = distS[x][y] + 1;
                            if (isdigit(capsule[nx][ny])) {
                                mf.addEdge(i * n + j, nx * n + ny + n * n, INF);
                            }
                            q2.push({nx, ny});
                        }
                    }
                }
            }
        }
    }

    cout << mf.computeMaxFlow(src, dst) << '\n';
    return 0;
}
